async getCustomerIdByEmail(email) {
    await this._searchRateLimitBucket.throttle();
    try {
        const result = await this._stripe.customers.search({
            query: `email:"${email}"`,
            limit: 10,
            expand: ['data.subscriptions']
        });
        const customers = result.data;

        if (customers.length === 0) {
            return null;
        }

        if (customers.length === 1) {
            return customers[0].id;
        }

        const bestCustomer = this._findMostRecentSubscriptionCustomer(customers);
        return bestCustomer ? bestCustomer.id : null;
    } catch (err) {
        debug(`getCustomerByEmail(${email}) -> ${err.type}:${err.message}`);
        return null;
    }
}

/**
 * Find the customer with the most recent subscription from an array of customers.
 * Expects customers to have subscriptions.expand already available.
 *
 * @param {import('stripe').Stripe.Customer[]} customers
 * @returns {import('stripe').Stripe.Customer|null}
 */
_findMostRecentSubscriptionCustomer(customers) {
    let latestCustomer = null;
    let latestSubscriptionTime = 0;

    for (const customer of customers) {
        const subscriptions = this._getValidSubscriptions(customer);
        for (const subscription of subscriptions) {
            if (subscription.current_period_end && subscription.current_period_end > latestSubscriptionTime) {
                latestSubscriptionTime = subscription.current_period_end;
                latestCustomer = customer;
            }
        }
    }

    return latestCustomer;
}

/**
 * Safely extract subscriptions array from a customer object.
 *
 * @param {import('stripe').Stripe.Customer} customer
 * @returns {import('stripe').Stripe.Subscription[]}
 */
_getValidSubscriptions(customer) {
    if (!customer.subscriptions || !customer.subscriptions.data) {
        return [];
    }
    return customer.subscriptions.data;
}

