 * @returns {Variable[]} unused variables of the scope and descendant scopes.
 * @private
 */
function collectUnusedVariables(scope, unusedVars) {
	const variables = scope.variables;
	const childScopes = scope.childScopes;

	if (shouldProcessScope(scope)) {
		for (const variable of variables) {
			if (isEligibleForProcessing(variable, scope)) {
				const def = variable.defs[0];
				if (def && isIgnoredDueToPattern(variable, def, scope)) {
					continue;
				}

				if (isUnusedAndNotExempt(variable, scope)) {
					unusedVars.push(variable);
				}
			}
		}
	}

	for (const childScope of childScopes) {
		collectUnusedVariables(childScope, unusedVars);
	}

	return unusedVars;
}

/**
 * Determines whether the current scope should be processed.
 * @param {Scope} scope The scope to check.
 * @returns {boolean} True if the scope should be processed.
 */
function shouldProcessScope(scope) {
	return scope.type !== "global" || config.vars === "all";
}

/**
 * Checks if a variable is eligible for processing in the given scope.
 * @param {Variable} variable The variable to check.
 * @param {Scope} scope The scope containing the variable.
 * @returns {boolean} True if the variable is eligible for processing.
 */
function isEligibleForProcessing(variable, scope) {
	if (isClassSelfReference(variable, scope)) {
		return false;
	}

	if (scope.functionExpressionScope) {
		return false;
	}

	if (shouldSkipReportedVariable(variable)) {
		return false;
	}

	if (isImplicitArgumentsVariable(variable, scope)) {
		return false;
	}

	return true;
}

/**
 * Checks if the variable is the class name in a class scope.
 * @param {Variable} variable The variable to check.
 * @param {Scope} scope The scope containing the variable.
 * @returns {boolean} True if the variable is the class name.
 */
function isClassSelfReference(variable, scope) {
	return (
		scope.type === "class" &&
		scope.block.id === variable.identifiers[0]
	);
}

/**
 * Checks if the variable should be skipped due to being marked as used.
 * @param {Variable} variable The variable to check.
 * @returns {boolean} True if the variable should be skipped.
 */
function shouldSkipReportedVariable(variable) {
	return (
		!config.reportUsedIgnorePattern &&
		variable.eslintUsed
	);
}

/**
 * Checks if the variable is the implicit 'arguments' variable in a function scope.
 * @param {Variable} variable The variable to check.
 * @param {Scope} scope The scope containing the variable.
 * @returns {boolean} True if the variable is the implicit 'arguments' variable.
 */
function isImplicitArgumentsVariable(variable, scope) {
	return (
		scope.type === "function" &&
		variable.name === "arguments" &&
		variable.identifiers.length === 0
	);
}

/**
 * Checks if a variable should be ignored due to matching an ignore pattern.
 * @param {Variable} variable The variable to check.
 * @param {Object} def The variable's definition.
 * @param {Scope} scope The scope containing the variable.
 * @returns {boolean} True if the variable should be ignored.
 */
function isIgnoredDueToPattern(variable, def, scope) {
	const variableType = defToVariableType(def);
	const [description, pattern] = getVariableDescription(variableType);

	if (!pattern) {
		return false;
	}

	if (pattern.test(def.name.name)) {
		if (config.reportUsedIgnorePattern && isUsedVariable(variable)) {
			reportUsedIgnoredVariable(variable, variableType);
		}
		return true;
	}

	return false;
}

/**
 * Reports a variable that matches an ignore pattern but is used.
 * @param {Variable} variable The variable to report.
 * @param {VariableType} variableType The type of the variable.
 */
function reportUsedIgnoredVariable(variable, variableType) {
	context.report({
		node: variable.defs[0].name,
		messageId: "usedIgnoredVar",
		data: getUsedIgnoredMessageData(variable, variableType),
	});
}

/**
 * Checks if a variable is unused and not exempt from reporting.
 * @param {Variable} variable The variable to check.
 * @param {Scope} scope The scope containing the variable.
 * @returns {boolean} True if the variable is unused and not exempt.
 */
function isUnusedAndNotExempt(variable, scope) {
	return (
		!isUsedVariable(variable) &&
		!isExported(variable) &&
		!(
			config.ignoreUsingDeclarations &&
			usesExplicitResourceManagement(variable)
		) &&
		!hasRestSpreadSibling(variable)
	);
}

