function handleBooleanOptions(options) {
  const booleanOptionKeys = [
    'useFindAndModify',
    'omitUndefined',
    'setDefaultsOnInsert',
    'overwriteDiscriminatorKey',
    'sanitizeProjection'
  ];

  for (const key of booleanOptionKeys) {
    if (key in options) {
      this._mongooseOptions[key] = options[key];
      delete options[key];
